from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
# crop x70-205 y28-105 make 4x upscaled image as PPM? use png in .tmp and perhaps inspect via OCR-like numeric not possible. We'll use cv2 connected shapes.
