# crop x70:155 y25:105 to braille (2x4 pixels per char), threshold dark
def braille(mask):
 chars=[]
 for y in range(0,mask.shape[0],4):
  line=''
  for x in range(0,mask.shape[1],2):
   bits=0
   for dy in range(4):
    for dx in range(2):
     if y+dy<mask.shape[0] and x+dx<mask.shape[1] and mask[y+dy,x+dx]: bits|=1<<(dx+dy*2)
   line+=chr(0x2800+bits)
  chars.append(line)
 return '\\n'.join(chars)
print(braille(m[25:105,70:155]))
